// VULNERABLE - String concatenation
public User loginVulnerable(String username, String password) {
    String sql = "SELECT * FROM users WHERE username='" + username + "' AND password='" + password + "'";
    // If username = "admin' OR '1'='1" the query becomes:
    // SELECT * FROM users WHERE username='admin' OR '1'='1' AND password='...'
    return jdbcTemplate.queryForObject(sql, new UserRowMapper());
}

// SAFE - PreparedStatement with parameters
public User loginSafe(String username, String password) {
    String sql = "SELECT * FROM users WHERE username = ? AND password = ?";
    return jdbcTemplate.queryForObject(sql, new UserRowMapper(), username, password);
    // The ? placeholders prevent SQL injection
    // User input is always treated as data, never as executable SQL
}

// ATTACK PAYLOAD EXAMPLE
// Username: admin' OR '1'='1' --
// Password: anything
// The -- comments out the rest of the query, bypassing authentication

public Optional<Order> findOrderById(Long orderId) {
    // Phase 1: SQL structure compilation
    String sql = "SELECT id, customer_name, total FROM orders WHERE id = ?";
    // The database receives this template and creates an execution plan
    // The ? is registered as a data parameter slot, not SQL code

    try (Connection conn = dataSource.getConnection();
         PreparedStatement pstmt = conn.prepareStatement(sql)) {

        // Phase 2: Data binding
        pstmt.setLong(1, orderId);  // Parameter index starts at 1
        // Even if orderId = "5 OR 1=1", it's treated as literal string "5 OR 1=1"
        // The SQL structure cannot change at this point

        try (ResultSet rs = pstmt.executeQuery()) {
            if (rs.next()) {
                return Optional.of(new Order(
                    rs.getLong("id"),
                    rs.getString("customer_name"),
                    rs.getBigDecimal("total")
                ));
            }
        }
    } catch (SQLException e) {
        throw new DataAccessException("Failed to fetch order", e);
    }
    return Optional.empty();
}

// SAFE - Repository method (Spring generates parameterized query)
public interface UserRepository extends JpaRepository<User, Long> {
    Optional<User> findByUsername(String username);  // No SQL injection risk
}

// SAFE - JPQL with named parameter
@Query("SELECT u FROM User u WHERE u.email = :email")
Optional<User> findByEmail(@Param("email") String email);

// SAFE - Native query with named parameter
@Query(value = "SELECT * FROM users WHERE status = :status", nativeQuery = true)
List<User> findByStatus(@Param("status") String status);

// VULNERABLE - Native query with concatenation
@Query(value = "SELECT * FROM users WHERE username = '" + "?1" + "'", nativeQuery = true)
User findByUsernameBad(String username);  // DON'T DO THIS

// VULNERABLE - JdbcTemplate with string building
public List<User> searchUsers(String searchTerm) {
    String sql = "SELECT * FROM users WHERE name LIKE '%" + searchTerm + "%'";
    return jdbcTemplate.query(sql, new UserRowMapper());  // Injection risk
}

// SAFE - JdbcTemplate with parameters
public List<User> searchUsersSafe(String searchTerm) {
    String sql = "SELECT * FROM users WHERE name LIKE ?";
    return jdbcTemplate.query(sql, new UserRowMapper(), "%" + searchTerm + "%");
}

// SCENARIO 1: Data destruction
// Payload: username = "admin'; DROP TABLE audit_logs; --"
// Resulting query:
// SELECT * FROM users WHERE username='admin'; DROP TABLE audit_logs; --' AND password='...'

// SCENARIO 2: Privilege escalation
// Payload: userId = "123; UPDATE users SET role='ADMIN' WHERE username='attacker'; --"
// Resulting query:
// UPDATE user_preferences SET theme='dark' WHERE user_id=123; 
// UPDATE users SET role='ADMIN' WHERE username='attacker'; -- ...

// SCENARIO 3: Blind SQL injection (time-based)
// Payload: id = "1 AND IF(SUBSTRING(password,1,1)='a', SLEEP(5), 0)"
// If the query takes 5 seconds, first character is 'a'
// Attacker repeats for each character to extract the full password

// SCENARIO 4: OS command execution (SQL Server)
// Payload: search = "test'; EXEC xp_cmdshell 'net user hacker pass123 /add'; --"
// Creates a Windows user account on the database server

// SCENARIO 5: File system access (MySQL)
// Payload: name = "admin' UNION SELECT LOAD_FILE('/etc/passwd') INTO OUTFILE '/tmp/data.txt'; --"
// Reads system files and writes output to attacker-controlled location

// LAYER 1: Input validation (allowlist)
public void validateUsername(String username) {
    if (!username.matches("^[a-zA-Z0-9_]{3,20}$")) {
        throw new IllegalArgumentException("Invalid username format");
    }
}

// LAYER 2: PreparedStatement (primary defense)
public Optional<User> findUser(String username) {
    validateUsername(username);  // Layer 1 checked first
    String sql = "SELECT id, username, email FROM users WHERE username = ?";
    return jdbcTemplate.queryForObject(sql, new UserRowMapper(), username);
}

// LAYER 3: Least privilege DB account configuration
// Database setup script (run as DBA):
// CREATE USER 'app_user'@'localhost' IDENTIFIED BY 'strong_password';
// GRANT SELECT, INSERT, UPDATE ON app_db.users TO 'app_user'@'localhost';
// GRANT SELECT, INSERT, UPDATE ON app_db.orders TO 'app_user'@'localhost';
// -- Explicitly NOT granting DROP, CREATE, ALTER, or DELETE on schema

// LAYER 4: ORM usage (Spring Data JPA)
@Repository
public interface UserRepository extends JpaRepository<User, Long> {
    @Query("SELECT u FROM User u WHERE u.username = :username")
    Optional<User> findByUsername(@Param("username") String username);
}
